begin;
create table if not exists public.enterprise_health_v31 (id bigserial primary key,account_name text not null default 'paper-main',health_date date not null,overall_score numeric not null default 0,database_score numeric not null default 0,data_score numeric not null default 0,pipeline_score numeric not null default 0,strategy_score numeric not null default 0,portfolio_score numeric not null default 0,risk_score numeric not null default 0,frontend_score numeric not null default 0,overall_status text not null,blockers jsonb not null default '[]'::jsonb,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists enterprise_health_v31_uidx on public.enterprise_health_v31(account_name,health_date);
create table if not exists public.daily_executive_reports_v31 (id bigserial primary key,account_name text not null default 'paper-main',report_date date not null,report_version text not null default '3.1.0',headline text not null,market_summary text not null,portfolio_summary text not null,risk_summary text not null,strategy_summary text not null,operations_summary text not null,action_items jsonb not null default '[]'::jsonb,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists daily_executive_reports_v31_uidx on public.daily_executive_reports_v31(account_name,report_date,report_version);
create table if not exists public.operations_center_v31 (id bigserial primary key,account_name text not null default 'paper-main',snapshot_date date not null,market_date date,signal_date date,pipeline_status text not null,data_status text not null,strategy_status text not null,portfolio_status text not null,risk_status text not null,frontend_status text not null,health_score numeric not null default 0,equity numeric not null default 0,cash numeric not null default 0,proposed_orders integer not null default 0,approved_orders integer not null default 0,filled_orders integer not null default 0,open_positions integer not null default 0,latest_action text,latest_report text,blockers jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create unique index if not exists operations_center_v31_uidx on public.operations_center_v31(account_name,snapshot_date);
alter table public.enterprise_health_v31 enable row level security; alter table public.daily_executive_reports_v31 enable row level security; alter table public.operations_center_v31 enable row level security;
drop policy if exists "enterprise31 read health" on public.enterprise_health_v31; drop policy if exists "enterprise31 read reports" on public.daily_executive_reports_v31; drop policy if exists "enterprise31 read operations" on public.operations_center_v31;
create policy "enterprise31 read health" on public.enterprise_health_v31 for select to anon,authenticated using(true); create policy "enterprise31 read reports" on public.daily_executive_reports_v31 for select to anon,authenticated using(true); create policy "enterprise31 read operations" on public.operations_center_v31 for select to anon,authenticated using(true);
notify pgrst,'reload schema'; commit; select 'GPT Quant Enterprise 3.1 Stable Core setup complete' as result;